                    sidebar: 'oklch(0.2 0.014 258)', 'sidebar-foreground': 'oklch(0.97 0.009 250)',
                    'sidebar-primary': 'oklch(0.585 0.2 262)', 'sidebar-primary-foreground': 'oklch(0.985 0.01 255)',
